package com.brightloop.tax;
import com.brightloop.catalog.ProductRepository;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.time.LocalDate;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/taxes") @PreAuthorize("hasRole('ADMIN')") public class TaxController {
 private final TaxRepository repo;private final ProductRepository products;public TaxController(TaxRepository r,ProductRepository p){repo=r;products=p;}
 public record Request(@NotBlank String name,@Pattern(regexp="PERCENTAGE|FIXED") String taxType,@NotNull @DecimalMin("0.0000") BigDecimal rate,String description,Long productId,LocalDate effectiveStart,LocalDate effectiveEnd,boolean active){}
 public record Response(Long id,String name,String taxType,BigDecimal rate,String description,Long productId,String productName,LocalDate effectiveStart,LocalDate effectiveEnd,boolean active){static Response of(Tax t){return new Response(t.id,t.name,t.taxType,t.rate,t.description,t.product==null?null:t.product.getId(),t.product==null?"All products":t.product.getName(),t.effectiveStart,t.effectiveEnd,t.active);}}
 @GetMapping public java.util.List<Response> list(){return repo.findAll().stream().map(Response::of).toList();}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) public Response create(@Valid @RequestBody Request r){var p=r.productId()==null?null:products.findById(r.productId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Product not found"));return Response.of(repo.save(new Tax(r.name(),r.taxType(),r.rate(),r.description(),p,r.effectiveStart(),r.effectiveEnd(),r.active())));}
 @PutMapping("/{id}") public Response update(@PathVariable Long id,@Valid @RequestBody Request r){var t=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Tax not found"));var p=r.productId()==null?null:products.findById(r.productId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Product not found"));t.update(r.name(),r.taxType(),r.rate(),r.description(),p,r.effectiveStart(),r.effectiveEnd(),r.active());return Response.of(t);}
 @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){repo.delete(repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Tax not found")));}
}
